/*
  TEAL ANDROID CAMERA PHONE
  Board: ESP32-S3 N16R8
  Camera: OV3660
  TFT: ILI9341 320x240
  Touch: XPT2046
  Storage: SD_MMC 1-bit

  Libraries:
  - Adafruit GFX Library
  - Adafruit ILI9341
  - XPT2046_Touchscreen

  ESP camera and SD_MMC are supplied by the
  Arduino ESP32 board package.

  Video files use a sequence of JPEG frames (.mjpg).
  They are not MP4 files.
*/

#include <Arduino.h>
#include <SPI.h>
#include <WiFi.h>
#include <FS.h>
#include <SD_MMC.h>
#include <esp_camera.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>
#include <XPT2046_Touchscreen.h>

// ---------------- DISPLAY ----------------
#define TFT_CS    1
#define TFT_DC    2
#define TFT_RST   14
#define TFT_SCLK  41
#define TFT_MOSI  42
#define TFT_MISO  21

#define TOUCH_CS  47
#define TOUCH_IRQ -1

Adafruit_ILI9341 tft(&SPI, TFT_DC, TFT_CS, TFT_RST);
XPT2046_Touchscreen touch(TOUCH_CS, TOUCH_IRQ);

// ---------------- SD CARD ----------------
// Assumed board wiring. Verify before uploading.
#define SD_CLK 39
#define SD_CMD 38
#define SD_D0  40

// ---------------- OV3660 CAMERA ----------------
#define CAM_PWDN  -1
#define CAM_RESET -1
#define CAM_XCLK  15
#define CAM_SIOD  4
#define CAM_SIOC  5
#define CAM_Y9    16
#define CAM_Y8    17
#define CAM_Y7    18
#define CAM_Y6    12
#define CAM_Y5    10
#define CAM_Y4    8
#define CAM_Y3    9
#define CAM_Y2    11
#define CAM_VSYNC 6
#define CAM_HREF  7
#define CAM_PCLK  13

// ---------------- COLORS ----------------
#define C_BG     0x0841
#define C_TEAL   0x04F5
#define C_DARK   0x024A
#define C_WHITE  0xFFFF
#define C_CYAN   0x07FF
#define C_RED    0xF800
#define C_GREEN  0x07E0
#define C_GRAY   0x8410
#define C_YELLOW 0xFFE0

enum Page {
  HOME,
  CAMERA_PAGE,
  CAMERA_SETTINGS,
  GALLERY_PAGE,
  STORAGE_PAGE,
  SETTINGS_PAGE,
  ABOUT_PAGE,
  SLEEP_PAGE
};

Page page = HOME;

bool sdReady = false;
bool cameraReady = false;
bool recording = false;
bool darkTheme = true;

File videoFile;

unsigned long lastTouch = 0;
unsigned long lastVideoFrame = 0;
unsigned long lastUIUpdate = 0;
unsigned long videoFrameCount = 0;

int photoCount = 0;
int videoCount = 0;

// Camera defaults
framesize_t cameraSize = FRAMESIZE_QVGA;
int jpegQuality = 12;
int exposureValue = 0;
int brightnessValue = 0;
int contrastValue = 0;
int saturationValue = 0;
int gainValue = 0;

int touchXMin = 200;
int touchXMax = 3900;
int touchYMin = 250;
int touchYMax = 3850;

uint16_t foreground() {
  return darkTheme ? C_WHITE : 0x0000;
}

uint16_t background() {
  return darkTheme ? C_BG : C_WHITE;
}

// ---------------- UI HELPERS ----------------

void button(int x, int y, int w, int h,
            const char *label, uint16_t color) {
  tft.fillRoundRect(x, y, w, h, 7, color);
  tft.drawRoundRect(x, y, w, h, 7, C_CYAN);

  tft.setTextColor(C_WHITE);
  tft.setTextSize(1);

  int16_t bx, by;
  uint16_t bw, bh;
  tft.getTextBounds(label, 0, 0, &bx, &by, &bw, &bh);
  tft.setCursor(x + (w - bw) / 2,
                y + (h - bh) / 2);
  tft.print(label);
}

void header(const char *title) {
  tft.fillScreen(background());
  tft.fillRect(0, 0, 320, 32, C_DARK);

  tft.setTextColor(C_WHITE);
  tft.setTextSize(2);
  tft.setCursor(7, 8);
  tft.print(title);

  button(270, 4, 44, 24, "HOME", C_TEAL);
}

void statusBar() {
  tft.fillRect(0, 223, 320, 17, 0x0000);
  tft.setTextSize(1);
  tft.setTextColor(C_CYAN);
  tft.setCursor(5, 228);
  tft.print("TEAL OS");

  tft.setCursor(90, 228);
  tft.setTextColor(sdReady ? C_GREEN : C_RED);
  tft.print(sdReady ? "SD OK" : "NO SD");

  tft.setCursor(165, 228);
  tft.setTextColor(cameraReady ? C_GREEN : C_RED);
  tft.print(cameraReady ? "CAM OK" : "CAM OFF");

  if (recording) {
    tft.setCursor(265, 228);
    tft.setTextColor(C_RED);
    tft.print("REC");
  }
}

// ---------------- STORAGE ----------------

bool createFolders() {
  if (!sdReady) return false;

  if (!SD_MMC.exists("/Photos")) {
    if (!SD_MMC.mkdir("/Photos")) return false;
  }

  if (!SD_MMC.exists("/Videos")) {
    if (!SD_MMC.mkdir("/Videos")) return false;
  }

  return true;
}

String numberedPath(const char *folder,
                    const char *prefix,
                    const char *extension) {
  char path[80];

  for (unsigned int n = 1; n < 100000; n++) {
    snprintf(path, sizeof(path), "%s/%s%05u%s",
             folder, prefix, n, extension);

    if (!SD_MMC.exists(path)) {
      return String(path);
    }
  }

  return String("");
}

void analyzeStorage() {
  photoCount = 0;
  videoCount = 0;

  if (!sdReady) return;

  File root = SD_MMC.open("/");
  if (!root) return;

  File entry = root.openNextFile();

  while (entry) {
    if (!entry.isDirectory()) {
      String name = String(entry.name());
      name.toLowerCase();

      if (name.endsWith(".jpg")) photoCount++;
      if (name.endsWith(".mjpg")) videoCount++;
    }
    entry.close();
    entry = root.openNextFile();
  }

  root.close();

  // Scan the media folders too.
  const char *folders[] = {"/Photos", "/Videos"};

  for (int f = 0; f < 2; f++) {
    File dir = SD_MMC.open(folders[f]);
    if (!dir || !dir.isDirectory()) {
      if (dir) dir.close();
      continue;
    }

    entry = dir.openNextFile();

    while (entry) {
      if (!entry.isDirectory()) {
        String name = String(entry.name());
        name.toLowerCase();

        if (name.endsWith(".jpg")) photoCount++;
        if (name.endsWith(".mjpg")) videoCount++;
      }
      entry.close();
      entry = dir.openNextFile();
    }

    dir.close();
  }
}

// ---------------- CAMERA ----------------

bool startCamera() {
  camera_config_t config = {};

  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer = LEDC_TIMER_0;

  config.pin_d0 = CAM_Y2;
  config.pin_d1 = CAM_Y3;
  config.pin_d2 = CAM_Y4;
  config.pin_d3 = CAM_Y5;
  config.pin_d4 = CAM_Y6;
  config.pin_d5 = CAM_Y7;
  config.pin_d6 = CAM_Y8;
  config.pin_d7 = CAM_Y9;

  config.pin_xclk = CAM_XCLK;
  config.pin_pclk = CAM_PCLK;
  config.pin_vsync = CAM_VSYNC;
  config.pin_href = CAM_HREF;
  config.pin_sccb_sda = CAM_SIOD;
  config.pin_sccb_scl = CAM_SIOC;
  config.pin_pwdn = CAM_PWDN;
  config.pin_reset = CAM_RESET;

  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG;
  config.frame_size = cameraSize;
  config.jpeg_quality = jpegQuality;
  config.fb_count = psramFound() ? 2 : 1;

  if (psramFound()) {
    config.fb_location = CAMERA_FB_IN_PSRAM;
    config.grab_mode = CAMERA_GRAB_LATEST;
  } else {
    config.fb_location = CAMERA_FB_IN_DRAM;
    config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
  }

  esp_err_t result = esp_camera_init(&config);

  if (result != ESP_OK) {
    Serial.printf("Camera init failed: 0x%x\n", result);
    cameraReady = false;
    return false;
  }

  cameraReady = true;

  sensor_t *sensor = esp_camera_sensor_get();

  if (sensor) {
    sensor->set_quality(sensor, jpegQuality);
    sensor->set_brightness(sensor, brightnessValue);
    sensor->set_contrast(sensor, contrastValue);
    sensor->set_saturation(sensor, saturationValue);
    sensor->set_exposure_ctrl(sensor, 1);
    sensor->set_gain_ctrl(sensor, 1);
  }

  Serial.println("Camera ready");
  return true;
}

void stopCamera() {
  if (recording && videoFile) {
    videoFile.flush();
    videoFile.close();
  }

  recording = false;

  if (cameraReady) {
    esp_camera_deinit();
  }

  cameraReady = false;
}

void applyCameraSettings() {
  if (!cameraReady) return;

  sensor_t *sensor = esp_camera_sensor_get();
  if (!sensor) return;

  sensor->set_quality(sensor, jpegQuality);
  sensor->set_brightness(sensor, brightnessValue);
  sensor->set_contrast(sensor, contrastValue);
  sensor->set_saturation(sensor, saturationValue);
}

// ---------------- PHOTO CAPTURE ----------------

bool takePhoto() {
  if (!cameraReady || !sdReady) return false;

  camera_fb_t *fb = esp_camera_fb_get();

  if (!fb) {
    Serial.println("Camera frame failed");
    return false;
  }

  String path = numberedPath("/Photos", "IMG_", ".jpg");

  if (!path.length()) {
    esp_camera_fb_return(fb);
    return false;
  }

  File file = SD_MMC.open(path.c_str(), FILE_WRITE);

  bool ok = false;

  if (file) {
    size_t written = file.write(fb->buf, fb->len);
    file.flush();
    file.close();
    ok = (written == fb->len);
  }

  esp_camera_fb_return(fb);

  if (ok) {
    Serial.print("Photo saved: ");
    Serial.println(path);
    analyzeStorage();
  } else {
    Serial.println("Photo save failed");
  }

  return ok;
}

// ---------------- VIDEO RECORDING ----------------

// This stores consecutive JPEG frames in an MJPEG
// stream file. It is not an AVI or MP4 container.
// Recording stops automatically if the SD card fills.

bool startVideo() {
  if (!cameraReady || !sdReady || recording) return false;

  String path = numberedPath("/Videos", "VID_", ".mjpg");
  if (!path.length()) return false;

  videoFile = SD_MMC.open(path.c_str(), FILE_WRITE);

  if (!videoFile) return false;

  videoFrameCount = 0;
  lastVideoFrame = millis();
  recording = true;

  Serial.print("Recording: ");
  Serial.println(path);

  return true;
}

void stopVideo() {
  if (!recording) return;

  recording = false;

  if (videoFile) {
    videoFile.flush();
    videoFile.close();
  }

  analyzeStorage();
  Serial.printf("Video frames: %lu\n", videoFrameCount);
}

void recordVideoFrame() {
  if (!recording || !cameraReady) return;

  // Limit recording to approximately 10 frames/second.
  if (millis() - lastVideoFrame < 100) return;
  lastVideoFrame = millis();

  camera_fb_t *fb = esp_camera_fb_get();

  if (!fb) return;

  // Frame length prefix followed by JPEG bytes.
  // A matching custom reader is required for playback.
  uint32_t len = fb->len;

  uint8_t prefix[4] = {
    (uint8_t)(len & 0xFF),
    (uint8_t)((len >> 8) & 0xFF),
    (uint8_t)((len >> 16) & 0xFF),
    (uint8_t)((len >> 24) & 0xFF)
  };

  size_t a = videoFile.write(prefix, sizeof(prefix));
  size_t b = videoFile.write(fb->buf, fb->len);

  esp_camera_fb_return(fb);

  if (a != sizeof(prefix) || b != len) {
    Serial.println("SD write failed; stopping recording");
    stopVideo();
    return;
  }

  videoFrameCount++;

  if ((videoFrameCount % 20) == 0) {
    videoFile.flush();
  }
}

// ---------------- SCREEN DRAWING ----------------

void drawHome() {
