  tft.print("ANDROID");

  tft.setTextSize(1);
  tft.setTextColor(C_WHITE);
  tft.setCursor(10, 30);
  tft.print("ESP32-S3 CAMERA PHONE");

  button(8, 57, 96, 49, "CAMERA", C_DARK);
  button(112, 57, 96, 49, "GALLERY", C_DARK);
  button(216, 57, 96, 49, "STORAGE", C_DARK);

  button(8, 114, 96, 49, "SETTINGS", C_DARK);
  button(112, 114, 96, 49, "ABOUT", C_DARK);
  button(216, 114, 96, 49, "SLEEP", C_DARK);

  tft.setTextColor(foreground());
  tft.setTextSize(1);
