  button(165, 44, 145, 48,
         recording ? "STOP VIDEO" : "RECORD", C_RED);

  button(10, 102, 145, 43, "SETTINGS", C_DARK);
  button(165, 102, 145, 43, "GALLERY", C_DARK);

  tft.setTextColor(foreground());
  tft.setTextSize(1);
  tft.setCursor(10, 161);

  if (!cameraReady) {
    tft.print("Camera unavailable. Check pin map.");
  } else {
    tft.print("Resolution: ");

