      case FRAMESIZE_HD:    tft.print("1280x720"); break;
      case FRAMESIZE_UXGA:  tft.print("1600x1200"); break;
      default:              tft.print("Other"); break;
    }
  }

  tft.setCursor(10, 181);
  tft.print("JPEG quality: ");
  tft.print(jpegQuality);
  tft.print(" (lower = higher quality)");

  tft.setCursor(10, 199);
  tft.print("Frames are saved to the SD card.");

  statusBar();
