void drawCameraSettings() {
  page = CAMERA_SETTINGS;
  header("CAM SETTINGS");

  button(8, 43, 96, 35, "QVGA", C_DARK);
  button(112, 43, 96, 35, "VGA", C_DARK);
  button(216, 43, 96, 35, "SVGA", C_DARK);

  button(8, 84, 96, 35, "QUALITY +", C_DARK);
  button(112, 84, 96, 35, "QUALITY -", C_DARK);
  button(216, 84, 96, 35, "RESTART", C_TEAL);

  button(8, 125, 96, 35, "BRIGHT +", C_DARK);
  button(112, 125, 96, 35, "BRIGHT -", C_DARK);
  button(216, 125, 96, 35, "CONTRAST", C_DARK);

  button(8, 166, 96, 35, "SATURATION", C_DARK);
