void drawStorage() {
  page = STORAGE_PAGE;
  header("STORAGE ANALYZER");

  if (!sdReady) {
    tft.setTextColor(C_RED);
    tft.setTextSize(2);
    tft.setCursor(10, 65);
    tft.print("SD not mounted");
    statusBar();
    return;
  }

  analyzeStorage();

  uint64_t total = SD_MMC.totalBytes();
  uint64_t used = SD_MMC.usedBytes();
  uint64_t freeBytes = total > used ? total - used : 0;

  tft.setTextColor(foreground());
  tft.setTextSize(2);
  tft.setCursor(10, 46);
  tft.print("Capacity");

  tft.setTextSize(1);
  tft.setCursor(10, 80);
  tft.print("Total: ");
  tft.print((unsigned long)(total / 1048576ULL));
  tft.print(" MB");

  tft.setCursor(10, 100);
  tft.print("Used: ");
  tft.print((unsigned long)(used / 1048576ULL));
  tft.print(" MB");

  tft.setCursor(10, 120);
  tft.print("Free: ");
  tft.print((unsigned long)(freeBytes / 1048576ULL));
  tft.print(" MB");

  int percent = total ? (int)((used * 100ULL) / total) : 0;

  tft.drawRect(10, 145, 300, 24, C_WHITE);
  tft.fillRect(12, 147, (296 * percent) / 100,
               20, C_TEAL);

  tft.setCursor(10, 178);
  tft.print("Used: ");
  tft.print(percent);
  tft.print("%");

  tft.setCursor(10, 194);
  tft.print("Photos: ");
  tft.print(photoCount);
  tft.print(" Videos: ");
  tft.print(videoCount);

  statusBar();
}

