  page = SLEEP_PAGE;
  tft.fillScreen(0x0000);
  tft.setTextColor(C_TEAL);
  tft.setTextSize(2);
  tft.setCursor(75, 100);
  tft.print("SLEEP MODE");

  tft.setTextSize(1);
  tft.setCursor(70, 130);
