// ---------------- CAMERA CONTROL ----------------

void changeResolution(framesize_t size) {
  if (recording) stopVideo();

  bool wasReady = cameraReady;
  stopCamera();

  cameraSize = size;

  if (wasReady) startCamera();

  drawCameraSettings();
}

// ---------------- TOUCH ----------------

bool readTouch(int &x, int &y) {
  if (!touch.touched()) return false;

  TS_Point p = touch.getPoint();

  // Initial landscape mapping. Calibrate if needed.
  x = map(p.y, touchYMin, touchYMax, 0, 319);
  y = map(p.x, touchXMin, touchXMax, 0, 239);

  x = constrain(x, 0, 319);
  y = constrain(y, 0, 239);

  return true;
}

void onTouch(int x, int y) {
  Serial.printf("Touch: %d,%d\n", x, y);

  if (page == SLEEP_PAGE) {
    drawHome();
    return;
  }

  if (x >= 270 && y < 32) {
    if (page == CAMERA_PAGE) drawCamera();
    else drawHome();
    return;
  }

  switch (page) {
    case HOME:
      if (y >= 57 && y < 106) {
        if (x < 108) {
          if (!cameraReady) startCamera();
          drawCamera();
        } else if (x < 212) {
          drawGallery();
        } else {
          drawStorage();
        }
      } else if (y >= 114 && y < 163) {
        if (x < 108) drawSettings();
        else if (x < 212) drawAbout();
        else drawSleep();
      }
      break;

    case CAMERA_PAGE:
      if (y >= 44 && y < 92) {
        if (x < 160) {
          if (takePhoto()) {
            tft.fillRect(0, 205, 320, 15, C_GREEN);
            tft.setTextColor(0x0000);
            tft.setTextSize(1);
            tft.setCursor(10, 209);
            tft.print("PHOTO SAVED");
            delay(250);
            drawCamera();
          } else {
            Serial.println("Photo failed");
          }
        } else {
          if (recording) stopVideo();
          else startVideo();
          drawCamera();
        }
      } else if (y >= 102 && y < 145) {
        if (x < 160) drawCameraSettings();
        else drawGallery();
      }
      break;

    case CAMERA_SETTINGS:
      if (y >= 43 && y < 78) {
        if (x < 108) changeResolution(FRAMESIZE_QVGA);
        else if (x < 212) changeResolution(FRAMESIZE_VGA);
        else changeResolution(FRAMESIZE_SVGA);
      } else if (y >= 84 && y < 119) {
        if (x < 108) jpegQuality = max(4, jpegQuality - 2);
        else if (x < 212) jpegQuality = min(30, jpegQuality + 2);
        else {
          stopCamera();
          startCamera();
        }
        applyCameraSettings();
        drawCameraSettings();
      } else if (y >= 125 && y < 160) {
        if (x < 108) brightnessValue = min(2, brightnessValue + 1);
        else if (x < 212) brightnessValue = max(-2, brightnessValue - 1);
        else contrastValue = (contrastValue >= 2) ? -2 : contrastValue + 1;
        applyCameraSettings();
        drawCameraSettings();
      } else if (y >= 166 && y < 201) {
        if (x < 108) {
          saturationValue = (saturationValue >= 2) ? -2 : saturationValue + 1;
        } else if (x < 212) {
          gainValue = !gainValue;
          if (cameraReady) {
            sensor_t *s = esp_camera_sensor_get();
            if (s) s->set_gain_ctrl(s, gainValue ? 1 : 0);
          }
        } else drawCamera();
        applyCameraSettings();
        drawCameraSettings();
      }
      break;

    case SETTINGS_PAGE:
      if (y >= 50 && y < 98) {
        if (x < 160) {
          darkTheme = !darkTheme;
          drawSettings();
        } else {
          if (!cameraReady) startCamera();
          drawCamera();
        }
      } else if (y >= 110 && y < 158) {
        if (x < 160) drawStorage();
        else drawAbout();
      }
      break;

    default:
      break;
  }
}

// ---------------- SETUP ----------------

void setup() {
  Serial.begin(115200);
  delay(300);

  SPI.begin(TFT_SCLK, TFT_MISO, TFT_MOSI);

  tft.begin();
  tft.setRotation(1);
  tft.fillScreen(C_BG);

  touch.begin();
  touch.setRotation(1);

  // Start SD card in 1-bit mode.
  if (SD_MMC.setPins(SD_CLK, SD_CMD, SD_D0)) {
    sdReady = SD_MMC.begin("/sdcard", true);
  } else {
    Serial.println("SD pin setup failed");
  }

  if (sdReady) {
    uint8_t type = SD_MMC.cardType();

    if (type == CARD_NONE) {
      sdReady = false;
      SD_MMC.end();
    } else {
      Serial.printf("SD size: %llu MB\n",
                    SD_MMC.cardSize() / (1024ULL * 1024ULL));
      createFolders();
    }
  }

  if (!sdReady) {
    Serial.println("SD unavailable; photos and video disabled");
  }

  startCamera();

  drawHome();
}

// ---------------- LOOP ----------------

void loop() {
  if (recording) {
    recordVideoFrame();
  }

  int x, y;

  if (readTouch(x, y)) {
    if (millis() - lastTouch > 250) {
      lastTouch = millis();
      onTouch(x, y);
    }
  }

  delay(5);
}

