/*
  ESP32-S3 N16R8 Mini Smartphone - ArduinoDroid starter firmware
  Hardware target:
    - ESP32-S3 WROOM N16R8
    - OV3660 camera (camera pin map below)
    - ILI9341 320x240 TFT
    - XPT2046 touch controller
    - Built-in microSD using SD_MMC 1-bit mode

  IMPORTANT:
    This is an integrated STARTER, not a fully verified phone OS.
    Camera, SD, touch, and board pin mapping must be checked against your exact
    OceanLabz board revision. Compile/test on the target board before relying on it.
    Wi-Fi scan/select, touchscreen password entry, browser text extraction,
    weather/time, JPEG photos, SD file listing, a basic hotspot, and Telegram
    sendMessage are included as prototypes. This is not a full smartphone OS.
    Internet audio, MJPEG AVI video recording, Telegram command polling/photo
    upload, full BLE scanning, rendered photo thumbnails, and full legal chess/Ludo
    rules are not implemented. Verify board pin maps and compile for your core.
*/

#include <Arduino.h>
#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <SPI.h>
#include <FS.h>
#include <LittleFS.h>
#include <SD_MMC.h>
#include <Preferences.h>
#include "esp_heap_caps.h"
#include <time.h>
#include "esp_camera.h"
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>
#include <XPT2046_Touchscreen.h>

// ---------- BOARD PINS: VERIFY AGAINST YOUR BOARD ----------
#define TFT_CS    1
#define TFT_DC    2
#define TFT_RST   14
#define TFT_SCLK  41
#define TFT_MOSI  42
#define TFT_MISO  21
#define TOUCH_CS  47
#define TOUCH_IRQ  -1

// HARDWARE PLACEHOLDERS: verify these pins are free on your exact board.
// GPIO45 is a strapping pin; keep the transistor input high-impedance at boot.
// GPIO48 may be shared with an onboard RGB LED on some board revisions.
#define TFT_BACKLIGHT_PIN 45
#define TORCH_PIN 48
#define BACKLIGHT_PWM_CHANNEL 6
#define BACKLIGHT_PWM_FREQ 5000
#define BACKLIGHT_PWM_BITS 8

// Camera pins supplied for this board family. Verify against exact revision.
#define CAM_PIN_SIOD 4
#define CAM_PIN_SIOC 5
#define CAM_PIN_VSYNC 6
#define CAM_PIN_HREF 7
#define CAM_PIN_XCLK 15
#define CAM_PIN_Y9 16
#define CAM_PIN_Y8 17
#define CAM_PIN_Y7 18
#define CAM_PIN_Y6 12
#define CAM_PIN_Y5 10
#define CAM_PIN_Y4 8
#define CAM_PIN_Y3 9
#define CAM_PIN_Y2 11
#define CAM_PIN_PCLK 13

// SD_MMC 1-bit pins supplied for the board.
#define SD_CLK 39
#define SD_CMD 38
#define SD_D0  40

static const int SCREEN_W = 320;
static const int SCREEN_H = 240;
uint16_t C_BG = 0x0841;
uint16_t C_PANEL = 0x10A3;
uint16_t C_TEAL = 0x4EFA;
uint16_t C_WHITE = 0xFFFF;
uint16_t C_MUTED = 0x9D7B;
uint16_t C_RED = 0xF800;
uint16_t C_GREEN = 0x07E0;
uint16_t C_YELLOW = 0xFFE0;

Adafruit_ILI9341 tft(TFT_CS, TFT_DC, TFT_RST);
XPT2046_Touchscreen touch(TOUCH_CS, TOUCH_IRQ);
Preferences prefs;

enum ScreenId {
  SCR_LOCK, SCR_HOME, SCR_WIFI, SCR_WIFI_SCAN, SCR_KEYBOARD, SCR_ALARM, SCR_BROWSER,
  SCR_MUSIC, SCR_CAMERA, SCR_GALLERY, SCR_GAMES, SCR_SETTINGS, SCR_ABOUT, SCR_TOUCH_CAL, SCR_FORMAT_SD, SCR_GAMEPLAY,
  SCR_APPS, SCR_FILES, SCR_MESSAGING, SCR_BLUETOOTH, SCR_PPG, SCR_QUICK, SCR_INTERNAL, SCR_SYSTEM_SETTINGS
};
ScreenId screenNow = SCR_LOCK;
ScreenId keyboardReturnScreen = SCR_HOME;

String pinCode = "1234";  // Change from Settings after first boot.
String pinEntry = "";
String keyboardText = "";
String keyboardTitle = "Enter text";
String wifiSsid = "";
String wifiPass = "";
String browserUrl = "http://example.com";
String radioUrl = "";
String statusLine = "Starting...";
String lastPhoto = "";
String alarmText = "07:00";
String alarmInput = "07:00";
bool alarmEnabled = false;
bool alarmRinging = false;
bool sdReady = false;
bool internalFsReady = false;
bool darkTheme = true;
uint32_t spaceShotTick = 0;
int spaceEnemyX = 160, spaceEnemyY = 60, spaceShotY = 180;
bool cameraReady = false;
bool wifiReady = false;
bool sleepMode = false;
bool showWifiPassword = false;
bool wifiConnectRequested = false;
bool browserOpenRequested = false;
bool cameraBusy = false;
bool gameStarted = false;
uint32_t lastTouchMs = 0;
uint32_t lastClockDrawMs = 0;
uint32_t lastAlarmCheckMs = 0;
uint32_t lastPhotoNumber = 1;
uint32_t lastWifiCheckMs = 0;
uint8_t selectedGame = 0;
int snakeX = 10, snakeY = 10, snakeDX = 1, snakeDY = 0;
uint32_t snakeTick = 0;
// Lightweight game and weather state. Games use partial redraws instead of wiping the TFT.
enum GameType { GAME_FLAPPY, GAME_DINO, GAME_CHESS, GAME_LUDO, GAME_DOOM, GAME_SNAKE, GAME_SPACE };
GameType activeGame = GAME_FLAPPY;
uint32_t lastGameFrameMs = 0;
int gamePlayerX = 55, gamePlayerY = 120, gameVelocity = 0, gameScore = 0;
int gameObstacleX = 300, gameObstacleY = 155;
bool gameOver = false;
String weatherText = "Weather: connect Wi-Fi";
String weatherTemp = "-- C";
uint32_t lastWeatherFetchMs = 0;
bool weatherFetchBusy = false;
TaskHandle_t networkTaskHandle = nullptr;
SemaphoreHandle_t weatherMutex = nullptr;
bool timeSyncRequested = false;

// Touch calibration raw limits. Values are persisted after the calibration wizard.
int touchRawXMin = 200, touchRawXMax = 3900;
int touchRawYMin = 250, touchRawYMax = 3850;
int calStep = 0;
int calRawX[4], calRawY[4];
bool psramAvailable = false;
bool keyboardShift = false;
bool keyboardSymbols = false;
String browserPageText = "Enter a URL and tap OPEN PAGE.";
String telegramBotToken = "";
String telegramChatId = "";
String telegramMessage = "Hello from Teal Phone";
String fileNames[12];
uint32_t fileSizes[12];
int fileCount = 0;
int filePage = 0;
String bluetoothStatus = "BLE scan not run";
int browserScroll = 0;
String wifiScanNames[8];
bool wifiScanOpen[8];
int wifiScanCount = 0;
uint8_t backlightLevel = 220;
bool torchOn = false;
bool quickShadeOpen = false;
uint32_t lastPpgSampleMs = 0;
uint32_t lastPpgBeatMs = 0;
float ppgBpm = 0.0f;
float ppgBaseline = 0.0f;
float ppgPrevious = 0.0f;
float ppgSmooth = 0.0f;
uint16_t ppgWave[120];
int ppgWaveIndex = 0;
bool ppgHaveSignal = false;
bool ppgModeActive = false;
int touchStartX = -1, touchStartY = -1;
bool swipeHandled = false;

static const char *NTP1 = "pool.ntp.org";
static const char *NTP2 = "time.google.com";

void drawHeader(const String &title);
void drawHome();
void drawCurrentScreen();
void drawKeyboard();
void startKeyboard(const String &title, const String &initial, ScreenId ret);
void handleTap(int x, int y);
bool getTouchPoint(int &x, int &y);
void connectWifi();
void scanWifiNetworks();
void openBrowserPage();
void initCamera();
void initCameraMode(bool ppgMode);
void drawPpgScreen();
void updateCameraPpg();
void drawQuickShade();
void setBacklight(uint8_t level);
void setTorch(bool on);
void setTheme(bool dark);
void initInternalFs();
void drawInternalStorage();
void initSd();
void capturePhoto();
void drawClockArea();
void checkAlarm();
void enterSleep();
void wakeScreen();
String getTimeString(bool withSeconds);
String getDateString();
void drawButton(int x, int y, int w, int h, const String &label, uint16_t color = 0x10A3);
void saveSettings();
void startTouchCalibration();
void handleTouchCalibration(int rawX, int rawY);
void drawTouchCalibration();
void drawGameMenu();
void startGame(GameType g);
void drawGameScene();
void updateGameFrame();
void handleGameTap(int x, int y);
void fetchWeather();
void networkTask(void *parameter);
void drawFileManager();
void refreshFileList();
void sendTelegramMessage();
String urlEncode(const String &input);

void setup() {
  Serial.begin(115200);
  delay(250);
  pinMode(TFT_BACKLIGHT_PIN, OUTPUT);
  ledcSetup(BACKLIGHT_PWM_CHANNEL, BACKLIGHT_PWM_FREQ, BACKLIGHT_PWM_BITS);
  ledcAttachPin(TFT_BACKLIGHT_PIN, BACKLIGHT_PWM_CHANNEL);
  setBacklight(backlightLevel);
  pinMode(TORCH_PIN, OUTPUT);
  digitalWrite(TORCH_PIN, LOW);
  prefs.begin("mini-phone", false);
  darkTheme = prefs.getBool("dark", true);
  setTheme(darkTheme);
  pinCode = prefs.getString("pin", "1234");
  wifiSsid = prefs.getString("ssid", "");
  wifiPass = prefs.getString("pass", "");
  alarmText = prefs.getString("alarm", "07:00");
  alarmEnabled = prefs.getBool("alarmOn", false);
  radioUrl = prefs.getString("radio", "");
  telegramBotToken = prefs.getString("tgToken", "");
  telegramChatId = prefs.getString("tgChat", "");
  touchRawXMin = prefs.getInt("txmin", 200);
  touchRawXMax = prefs.getInt("txmax", 3900);
  touchRawYMin = prefs.getInt("tymin", 250);
  touchRawYMax = prefs.getInt("tymax", 3850);
  backlightLevel = (uint8_t)prefs.getUChar("bl", 220);
  psramAvailable = psramFound() && ESP.getPsramSize() > 0;
  Serial.printf("PSRAM found: %s; size=%u; free=%u\n",
                psramAvailable ? "YES" : "NO",
                (unsigned)ESP.getPsramSize(), (unsigned)ESP.getFreePsram());

  SPI.begin(TFT_SCLK, TFT_MISO, TFT_MOSI);
  tft.begin();
  tft.setRotation(1);
  tft.fillScreen(C_BG);
  tft.setTextWrap(false);
  touch.begin(SPI);
  touch.setRotation(1);

  initInternalFs();
  initSd();
  initCamera();

  statusLine = "Ready";
  drawCurrentScreen();
  lastTouchMs = millis();

  // Connect to saved Wi-Fi if credentials exist.
  weatherMutex = xSemaphoreCreateMutex();

  if (wifiSsid.length() > 0) {
    WiFi.mode(WIFI_STA);
    WiFi.begin(wifiSsid.c_str(), wifiPass.c_str());
  }

  // ESP32-S3 dual-core split: network/weather work on core 0;
  // Arduino UI, touch and game drawing stay in loop() on core 1.
  BaseType_t taskOk = xTaskCreatePinnedToCore(
    networkTask, "PhoneNetwork", 8192, nullptr, 1,
    &networkTaskHandle, 0);
  if (taskOk != pdPASS) {
    Serial.println("WARNING: network task failed; Wi-Fi/weather background task unavailable");
  } else {
    Serial.println("Network task started on core 0; UI/game loop on core 1");
  }
}

void loop() {

  int tx, ty;
  if (getTouchPoint(tx, ty)) {
    lastTouchMs = millis();
    if (touchStartX < 0) { touchStartX = tx; touchStartY = ty; swipeHandled = false; }
    int dy = ty - touchStartY;
    if (!swipeHandled && touchStartY < 32 && dy > 45) {
      quickShadeOpen = true;
      drawQuickShade(); swipeHandled = true;
    } else if (!swipeHandled && quickShadeOpen && dy < -45) {
      quickShadeOpen = false; drawCurrentScreen(); swipeHandled = true;
    } else if (!swipeHandled && quickShadeOpen) {
      handleTap(tx, ty);
      swipeHandled = true;
    } else if (!swipeHandled) {
      if (sleepMode) wakeScreen();
      else if (alarmRinging) { alarmRinging = false; drawCurrentScreen(); }
      else handleTap(tx, ty);
      // Allow swipe recognition when a finger starts at the top edge.
      if (touchStartY >= 32) swipeHandled = true;
    }
    delay(35);
  } else { touchStartX = -1; touchStartY = -1; swipeHandled = false; }

  if (screenNow == SCR_PPG && ppgModeActive && !sleepMode && millis() - lastPpgSampleMs >= 100) {
    lastPpgSampleMs = millis(); updateCameraPpg();
  }

  if (screenNow == SCR_GAMEPLAY && !sleepMode && millis() - lastGameFrameMs >= 33) {
    lastGameFrameMs = millis();
    updateGameFrame();
  }
  checkAlarm();

  // Redraw clock/status once per second without clearing the full screen.
  if (millis() - lastClockDrawMs >= 1000) {
    lastClockDrawMs = millis();
    if (screenNow == SCR_HOME && !sleepMode) drawClockArea();
  }

  // Dim/blank screen after 60 seconds of inactivity.
  if (!sleepMode && millis() - lastTouchMs > 60000UL && !alarmRinging) {
    enterSleep();
  }

  if (screenNow == SCR_CAMERA && cameraBusy) delay(1);
}

bool getTouchPoint(int &x, int &y) {
  if (!touch.touched()) return false;
  TS_Point p = touch.getPoint();
  if (screenNow == SCR_TOUCH_CAL) {
    handleTouchCalibration(p.x, p.y);
    return false;
  }
  x = map(p.x, touchRawXMin, touchRawXMax, 0, SCREEN_W - 1);
  y = map(p.y, touchRawYMin, touchRawYMax, 0, SCREEN_H - 1);
  x = constrain(x, 0, SCREEN_W - 1);
  y = constrain(y, 0, SCREEN_H - 1);
  return true;
}

void initSd() {
  Serial.println();
  Serial.println("=== microSD diagnostic ===");
  Serial.printf("PSRAM: %u bytes total, %u bytes free\n",
                (unsigned int)ESP.getPsramSize(),
                (unsigned int)ESP.getFreePsram());
  Serial.printf("SD pins (CLK/CMD/D0): %d / %d / %d\n",
                SD_CLK, SD_CMD, SD_D0);
  Serial.println("Starting SD_MMC in 1-bit mode...");

  // Clear any previous mount before trying again from the Gallery screen.
  SD_MMC.end();

  if (!SD_MMC.setPins(SD_CLK, SD_CMD, SD_D0)) {
    Serial.println("ERROR: SD_MMC.setPins failed. Check the board pin map.");
    sdReady = false;
    statusLine = "SD pin setup failed";
    return;
  }

  if (!SD_MMC.begin("/sdcard", true)) { // 1-bit mode
    Serial.println("ERROR: SD_MMC.begin failed.");
    Serial.println("Check card seating, FAT32 format, and exact board SD pins.");
    sdReady = false;
    statusLine = "SD init failed; see Serial";
    return;
  }

  uint8_t type = SD_MMC.cardType();
  if (type == CARD_NONE) {
    Serial.println("ERROR: No SD card detected after mounting.");
    SD_MMC.end();
    sdReady = false;
    statusLine = "No SD card detected";
    return;
  }

  uint64_t cardBytes = SD_MMC.cardSize();
  Serial.printf("Card type: %u\n", type);
  Serial.printf("Card size: %llu MB\n",
                (unsigned long long)(cardBytes / (1024ULL * 1024ULL)));

  File root = SD_MMC.open("/");
  if (!root || !root.isDirectory()) {
    Serial.println("ERROR: Card mounted, but root directory could not be opened.");
    sdReady = false;
    statusLine = "SD root open failed";
    return;
  }

  lastPhoto = "";
  File f = root.openNextFile();
  while (f) {
    String n = String(f.name());
    if (n.endsWith(".jpg") || n.endsWith(".JPG")) lastPhoto = n;
    f.close();
    f = root.openNextFile();
  }
  root.close();

  sdReady = true;
  statusLine = "SD card ready";
  Serial.println("SD CARD READY");
  Serial.println("==========================");
}

void initCamera() { initCameraMode(false); }

void initCameraMode(bool ppgMode) {
  camera_config_t c;
  c.ledc_channel = LEDC_CHANNEL_0;
  c.ledc_timer = LEDC_TIMER_0;
  c.pin_d0 = CAM_PIN_Y2;
  c.pin_d1 = CAM_PIN_Y3;
  c.pin_d2 = CAM_PIN_Y4;
  c.pin_d3 = CAM_PIN_Y5;
  c.pin_d4 = CAM_PIN_Y6;
  c.pin_d5 = CAM_PIN_Y7;
  c.pin_d6 = CAM_PIN_Y8;
  c.pin_d7 = CAM_PIN_Y9;
  c.pin_xclk = CAM_PIN_XCLK;
  c.pin_pclk = CAM_PIN_PCLK;
  c.pin_vsync = CAM_PIN_VSYNC;
  c.pin_href = CAM_PIN_HREF;
  c.pin_sccb_sda = CAM_PIN_SIOD;
  c.pin_sccb_scl = CAM_PIN_SIOC;
  c.pin_pwdn = -1;
  c.pin_reset = -1;
  c.xclk_freq_hz = 20000000;
  c.pixel_format = ppgMode ? PIXFORMAT_RGB565 : PIXFORMAT_JPEG;
  c.frame_size = ppgMode ? FRAMESIZE_QQVGA : FRAMESIZE_QVGA;
  c.jpeg_quality = 12;
  c.fb_count = ppgMode ? 1 : (psramAvailable ? 2 : 1);
  c.grab_mode = CAMERA_GRAB_LATEST;
  c.fb_location = psramAvailable ? CAMERA_FB_IN_PSRAM : CAMERA_FB_IN_DRAM;
  cameraReady = (esp_camera_init(&c) == ESP_OK);
  ppgModeActive = ppgMode && cameraReady;
}

void drawHeader(const String &title) {
  tft.fillRect(0, 0, SCREEN_W, 30, C_PANEL);
  tft.setTextColor(C_TEAL);
  tft.setTextSize(2);
  tft.setCursor(8, 7);
  tft.print(title);
  tft.setTextSize(1);
  tft.setTextColor(C_WHITE);
  tft.setCursor(260, 10);
  tft.print(wifiReady ? "WiFi" : "OFF");
}

void drawButton(int x, int y, int w, int h, const String &label, uint16_t color) {
  tft.fillRoundRect(x, y, w, h, 7, color);
  tft.drawRoundRect(x, y, w, h, 7, C_TEAL);
  tft.setTextColor(C_WHITE);
  tft.setTextSize(1);
  int tw = label.length() * 6;
  tft.setCursor(x + max(4, (w - tw) / 2), y + h / 2 - 4);
  tft.print(label);
}

String getTimeString(bool withSeconds) {
  struct tm ti;
  if (!getLocalTime(&ti, 10)) return String("--:--");
  char b[16];
  if (withSeconds) strftime(b, sizeof(b), "%H:%M:%S", &ti);
  else strftime(b, sizeof(b), "%H:%M", &ti);
  return String(b);
}

String getDateString() {
  struct tm ti;
  if (!getLocalTime(&ti, 10)) return String("Waiting for Wi-Fi time");
  char b[24];
  strftime(b, sizeof(b), "%a, %d %b %Y", &ti);
  return String(b);
}

void drawClockArea() {
  tft.fillRect(0, 34, 320, 52, C_BG);
  tft.setTextColor(C_WHITE);
  tft.setTextSize(3);
  tft.setCursor(70, 40);
  tft.print(getTimeString(false));
  tft.setTextSize(1);
  tft.setTextColor(C_MUTED);
  tft.setCursor(78, 69);
  tft.print(getDateString());
  tft.setTextColor(C_TEAL);
  tft.setCursor(8, 83);
  String weatherLine;
  if (weatherMutex && xSemaphoreTake(weatherMutex, pdMS_TO_TICKS(10)) == pdTRUE) {
    weatherLine = weatherText;
    xSemaphoreGive(weatherMutex);
  } else {
    weatherLine = "Weather updating...";
  }
  tft.print(weatherLine.substring(0, 50));
}

void drawHome() {
  tft.fillScreen(C_BG);
  drawHeader("TEAL PHONE");
  tft.fillRect(0, 30, 320, 3, C_TEAL);
  drawClockArea();
  drawButton(10, 94, 92, 48, "CAMERA", C_PANEL);
  drawButton(114, 94, 92, 48, "BROWSER", C_PANEL);
  drawButton(218, 94, 92, 48, "MUSIC", C_PANEL);
  drawButton(10, 151, 92, 48, "WI-FI", C_PANEL);
  drawButton(114, 151, 92, 48, "ALARM", C_PANEL);
  drawButton(218, 151, 92, 48, "GAMES", C_PANEL);
  drawButton(10, 207, 92, 25, "GALLERY", C_PANEL);
  drawButton(114, 207, 92, 25, "SETTINGS", C_PANEL);
  drawButton(218, 207, 92, 25, "APPS", C_PANEL);
}

void drawCurrentScreen() {
  tft.fillScreen(C_BG);
  switch (screenNow) {
    case SCR_LOCK:
      drawHeader("LOCK SCREEN");
      tft.setTextColor(C_WHITE); tft.setTextSize(3);
      tft.setCursor(85, 52); tft.print(getTimeString(false));
      tft.setTextSize(1); tft.setTextColor(C_MUTED);
      tft.setCursor(65, 87); tft.print(getDateString());
      tft.setTextColor(C_TEAL); tft.setTextSize(2);
      tft.setCursor(88, 113); tft.print("Enter PIN");
      tft.fillRoundRect(50, 139, 220, 27, 6, C_PANEL);
      tft.setCursor(105, 147); tft.setTextColor(C_WHITE);
      for (unsigned int i=0; i<pinEntry.length(); i++) tft.print("* ");
      drawButton(45, 178, 52, 26, "1"); drawButton(106,178,52,26,"2");
      drawButton(167,178,52,26,"3"); drawButton(228,178,47,26,"DEL");
      drawButton(45, 209, 52, 26, "4"); drawButton(106,209,52,26,"5");
      drawButton(167,209,52,26,"6"); drawButton(228,209,47,26,"OK");
      break;
    case SCR_HOME: drawHome(); break;
    case SCR_WIFI:
      drawHeader("WI-FI SETTINGS");
      tft.setTextColor(C_WHITE); tft.setTextSize(1);
      tft.setCursor(10, 45); tft.print("Status: "); tft.print(WiFi.status()==WL_CONNECTED ? "Connected" : "Disconnected");
      tft.setCursor(10, 62); tft.print("Network: "); tft.print(wifiSsid);
      drawButton(10, 82, 145, 34, "SCAN NETWORKS");
      drawButton(165,82,145,34,"SET PASSWORD");
      drawButton(10, 124, 145, 34, "CONNECT");
      drawButton(165,124,145,34,"DISCONNECT");
      drawButton(10, 166, 145, 34, "HOTSPOT (DEMO)");
      drawButton(165,166,145,34,"BACK");
      tft.setCursor(10, 214); tft.setTextColor(C_MUTED);
      tft.print("Tap Network to type manually; scan to choose.");
      break;
    case SCR_WIFI_SCAN:
      drawHeader("NEARBY WI-FI");
      tft.setTextColor(C_MUTED); tft.setTextSize(1);
      tft.setCursor(10, 35); tft.print("Tap a network to select it");
      for (int i = 0; i < wifiScanCount && i < 5; i++) {
        int yy = 53 + i * 31;
        drawButton(8, yy, 304, 27, wifiScanNames[i].substring(0, 30), C_PANEL);
      }
      drawButton(8, 213, 145, 24, "RESCAN");
      drawButton(165, 213, 147, 24, "BACK");
      break;
    case SCR_KEYBOARD: drawKeyboard(); break;
    case SCR_ALARM:
      drawHeader("ALARM");
      tft.setTextColor(C_WHITE); tft.setTextSize(2);
      tft.setCursor(20, 52); tft.print("Alarm: "); tft.print(alarmText);
