void setTheme(bool dark) {
  darkTheme = dark;
  if (dark) {
    C_BG = 0x0841; C_PANEL = 0x10A3; C_TEAL = 0x4EFA;
    C_WHITE = 0xFFFF; C_MUTED = 0x9D7B; C_RED = 0xF800;
    C_GREEN = 0x07E0; C_YELLOW = 0xFFE0;
  } else {
    C_BG = 0xFFFF; C_PANEL = 0xD69A; C_TEAL = 0x03EF;
    C_WHITE = 0x0000; C_MUTED = 0x630C; C_RED = 0xF800;
