  }
  prefs.putBool("dark", darkTheme);
}

void initInternalFs() {
  Serial.println("Mounting internal LittleFS without formatting...");
  internalFsReady = LittleFS.begin(false);
  if (!internalFsReady) {
    Serial.println("LittleFS mount failed; no automatic format performed.");
    return;
  }
  if (!LittleFS.exists("/phone")) LittleFS.mkdir("/phone");
  if (!LittleFS.exists("/phone/welcome.txt")) {
    File f = LittleFS.open("/phone/welcome.txt", FILE_WRITE);
    if (f) { f.println("Teal Phone internal storage"); f.println("Settings survive power off."); f.close(); }
  }
  Serial.printf("LittleFS total=%u used=%u bytes\n", (unsigned)LittleFS.totalBytes(), (unsigned)LittleFS.usedBytes());
}

