void updateCameraPpg() {
  if (!cameraReady || !ppgModeActive) return;
  camera_fb_t *fb = esp_camera_fb_get();
  if (!fb) return;
  if (fb->format == PIXFORMAT_RGB565 && fb->len >= 2) {
    const uint16_t *pix = (const uint16_t *)fb->buf;
    size_t count = fb->len / 2;
    uint64_t redSum = 0;
    size_t sampled = 0;
    // Sample every fourth pixel to reduce CPU cost. RGB565 red is bits 11..15.
    for (size_t i=0; i<count; i+=4) { redSum += (pix[i] >> 11) & 0x1F; sampled++; }
    if (sampled) {
      float raw = (float)redSum / (float)sampled;
      if (ppgSmooth == 0.0f) ppgSmooth = raw;
      ppgSmooth = 0.75f * ppgSmooth + 0.25f * raw;
      float ac = raw - ppgSmooth;
      ppgBaseline = 0.90f * ppgBaseline + 0.10f * ac;
      float signal = ac - ppgBaseline;
      int bar = constrain((int)(32.0f + signal * 8.0f), 2, 58);
      ppgWave[ppgWaveIndex] = (uint16_t)bar;
      ppgWaveIndex = (ppgWaveIndex + 1) % 120;
      if (raw > 1.5f) ppgHaveSignal = true;
      uint32_t now = millis();
      // Rising threshold crossing; finger movement/light changes can create false beats.
      float threshold = 0.8f;
      if (ppgPrevious <= threshold && signal > threshold && now - lastPpgBeatMs > 300) {
        if (lastPpgBeatMs != 0) {
          uint32_t interval = now - lastPpgBeatMs;
          float bpm = 60000.0f / (float)interval;
          if (bpm >= 35.0f && bpm <= 200.0f) ppgBpm = (ppgBpm == 0.0f) ? bpm : 0.7f * ppgBpm + 0.3f * bpm;
        }
        lastPpgBeatMs = now;
      }
      ppgPrevious = signal;
      // Refresh only the app every 400 ms, not the full device display.
      static uint32_t lastDraw = 0;
      if (now - lastDraw >= 400) { lastDraw = now; drawPpgScreen(); }
    }
  }
  esp_camera_fb_return(fb);
}

