void drawGameScene() {
  tft.fillScreen(C_BG);
  String title = "GAME";
  if (activeGame == GAME_FLAPPY) title = "FLAPPY BIRD";
  else if (activeGame == GAME_DINO) title = "CHROME DINO";
  else if (activeGame == GAME_CHESS) title = "CHESS - LOCAL 2P";
  else if (activeGame == GAME_LUDO) title = "LUDO DICE";
  else if (activeGame == GAME_DOOM) title = "DOOM-STYLE MAZE";
  else if (activeGame == GAME_SNAKE) title = "SNAKE";
  else if (activeGame == GAME_SPACE) title = "SPACE WARRIOR";
  drawHeader(title);
  tft.setTextColor(C_WHITE); tft.setTextSize(1);
  if (activeGame == GAME_FLAPPY) {
    tft.drawFastHLine(0, 210, 320, C_GREEN);
    tft.fillCircle(gamePlayerX, gamePlayerY, 7, C_YELLOW);
    tft.fillRect(gameObstacleX, 42, 24, max(0, gameObstacleY - 55), C_GREEN);
    tft.fillRect(gameObstacleX, gameObstacleY + 48, 24, max(0, 210 - gameObstacleY - 48), C_GREEN);
    tft.setCursor(8, 35); tft.print("Tap anywhere to flap. Score: "); tft.print(gameScore);
  } else if (activeGame == GAME_DINO) {
    tft.drawFastHLine(0, 202, 320, C_WHITE);
    tft.fillRect(gamePlayerX, gamePlayerY - 24, 16, 24, C_WHITE);
    tft.fillRect(gamePlayerX + 10, gamePlayerY - 33, 12, 12, C_WHITE);
    tft.fillRect(gameObstacleX, 179, 10, 23, C_GREEN);
    tft.setCursor(8, 35); tft.print("Tap to jump. Score: "); tft.print(gameScore);
  } else if (activeGame == GAME_CHESS) {
    int cell = 25, ox = 60, oy = 43;
    for (int r=0;r<6;r++) for(int c=0;c<8;c++) {
      uint16_t col = ((r+c)&1) ? C_PANEL : C_MUTED;
      tft.fillRect(ox+c*cell, oy+r*cell, cell, cell, col);
      // Lightweight chess-like local board with piece markers; not a full rules engine.
      if (r==0 || r==5 || r==1 || r==4) {
        if ((r==0 || r==5) || ((c+r)%2==0 && (r==1 || r==4))) {
          tft.setTextColor((r<3)?C_WHITE:C_BG); tft.setCursor(ox+c*cell+8, oy+r*cell+8);
          const char *pieces = "RNBQKBNR"; tft.print((r==0||r==5)?String(pieces[c]):"P");
        }
      }
    }
    tft.setTextColor(C_WHITE); tft.setCursor(8, 207); tft.print("Tap board to select/move (demo rules)");
  } else if (activeGame == GAME_LUDO) {
    tft.drawRoundRect(48, 43, 224, 150, 12, C_WHITE);
    tft.fillRect(55, 50, 75, 60, C_RED); tft.fillRect(190, 50, 75, 60, C_GREEN);
    tft.fillRect(55, 125, 75, 60, C_YELLOW); tft.fillRect(190, 125, 75, 60, C_TEAL);
    tft.fillCircle(160, 118, 25, C_WHITE); tft.setTextColor(C_BG); tft.setTextSize(3);
    tft.setCursor(151, 105); tft.print((gameScore%6)+1); tft.setTextSize(1);
    tft.setTextColor(C_WHITE); tft.setCursor(10, 207); tft.print("Tap to roll dice");
  } else if (activeGame == GAME_DOOM) {
    // Simple 2.5D ray-cast style corridor scene, not the original Doom engine.
    for (int y=43;y<122;y++) tft.drawFastHLine(0,y,320, (y%3==0)?C_MUTED:C_PANEL);
    for (int y=122;y<211;y++) tft.drawFastHLine(0,y,320, (y%4==0)?C_PANEL:C_BG);
    tft.fillRect(92, 75, 136, 86, C_MUTED); tft.fillRect(106, 87, 108, 74, C_BG);
    tft.drawRect(106, 87, 108, 74, C_TEAL);
    tft.setTextColor(C_WHITE); tft.setCursor(8, 35); tft.print("Tap to move forward. Distance: "); tft.print(gameScore);
  } else if (activeGame == GAME_SNAKE) {
    tft.drawRect(8, 43, 304, 160, C_MUTED);
    tft.fillRect(gamePlayerX, gamePlayerY, 8, 8, C_TEAL);
    tft.fillCircle(gameObstacleX, gameObstacleY, 4, C_RED);
    tft.setCursor(8, 207); tft.print("Tap sides or top/bottom to steer");
  } else if (activeGame == GAME_SPACE) {
    tft.setTextColor(C_WHITE); tft.setCursor(8, 35); tft.print("Tap to fire! Score: "); tft.print(gameScore);
    for (int i=0;i<22;i++) tft.drawPixel((i*47 + gameScore*3)%320, 45+(i*31)%155, C_MUTED);
