}

void updateGameFrame() {
  if (gameOver) return;
  if (activeGame == GAME_FLAPPY) {
    int oldY = gamePlayerY;
    gameVelocity += 1;
    gamePlayerY += gameVelocity;
    gameObstacleX -= 3;
    if (gameObstacleX < -25) { gameObstacleX = 320; gameObstacleY = 85 + (esp_random()%85); gameScore++; }
    if (gamePlayerY < 48 || gamePlayerY > 205 || (gamePlayerX+7 > gameObstacleX && gamePlayerX-7 < gameObstacleX+24 && (gamePlayerY-7 < gameObstacleY || gamePlayerY+7 > gameObstacleY+48))) gameOver=true;
    tft.fillRect(0, 43, 320, 167, C_BG);
    tft.drawFastHLine(0,210,320,C_GREEN);
    tft.fillRect(gameObstacleX,42,24,max(0,gameObstacleY-55),C_GREEN);
    tft.fillRect(gameObstacleX,gameObstacleY+48,24,max(0,210-gameObstacleY-48),C_GREEN);
    tft.fillCircle(gamePlayerX, gamePlayerY, 7, C_YELLOW);
    tft.fillRect(175, 34, 140, 8, C_BG); tft.setCursor(175,35); tft.setTextColor(C_WHITE); tft.print("Score:"); tft.print(gameScore);
  } else if (activeGame == GAME_DINO) {
    gameObstacleX -= 4; if(gameObstacleX < -12) { gameObstacleX=320; gameScore++; }
    if (gamePlayerY < 178) { gameVelocity += 1; gamePlayerY += gameVelocity; if(gamePlayerY > 178) { gamePlayerY=178; gameVelocity=0; } }
    if (gameObstacleX < gamePlayerX+18 && gameObstacleX+10 > gamePlayerX && gamePlayerY >= 178) gameOver=true;
    tft.fillRect(0, 43, 320, 160, C_BG); tft.drawFastHLine(0,202,320,C_WHITE);
    tft.fillRect(gamePlayerX,gamePlayerY-24,16,24,C_WHITE); tft.fillRect(gamePlayerX+10,gamePlayerY-33,12,12,C_WHITE);
    tft.fillRect(gameObstacleX,179,10,23,C_GREEN); tft.fillRect(220,34,90,8,C_BG); tft.setCursor(220,35); tft.setTextColor(C_WHITE); tft.print(gameScore);
  } else if (activeGame == GAME_LUDO) {
    // Dice turn animation; tap to roll and advance the displayed turn.
    if (millis() - lastGameFrameMs > 900) { tft.fillRect(130, 91, 60, 55, C_WHITE); tft.setTextColor(C_BG); tft.setTextSize(3); tft.setCursor(151,105); tft.print((gameScore%6)+1); tft.setTextSize(1); }
  } else if (activeGame == GAME_DOOM) {
    // Animate a subtle forward corridor movement without full-screen clearing.
    int shift = gameScore % 12;
    tft.drawFastHLine(106, 87+shift, 108, C_TEAL); tft.drawFastHLine(106, 161-shift, 108, C_TEAL);
  } else if (activeGame == GAME_SPACE) {
    if (millis() - spaceShotTick >= 90) {
      spaceShotTick = millis(); spaceShotY -= 12;
      if (spaceShotY < 48) { spaceShotY = gamePlayerY - 15; }
      spaceEnemyY += 2; if (spaceEnemyY > 190) { spaceEnemyY = 48; spaceEnemyX = 20 + (esp_random() % 280); }
      if (abs(spaceEnemyX-gamePlayerX) < 13 && abs(spaceEnemyY-spaceShotY) < 18) { gameScore++; spaceEnemyY = 48; spaceEnemyX = 20 + (esp_random() % 280); spaceShotY = gamePlayerY-15; }
      if (spaceEnemyY > 180 && abs(spaceEnemyX-gamePlayerX) < 15) gameOver = true;
      tft.fillRect(0, 43, 320, 170, C_BG);
      for (int i=0;i<22;i++) tft.drawPixel((i*47 + gameScore*3)%320, 45+(i*31)%155, C_MUTED);
      tft.fillTriangle(gamePlayerX, 190, gamePlayerX-10, 207, gamePlayerX+10, 207, C_TEAL);
      tft.fillRect(spaceEnemyX-8, spaceEnemyY-5, 16, 10, C_RED);
      tft.drawFastVLine(gamePlayerX, spaceShotY, 10, C_YELLOW);
      tft.fillRect(175,34,140,8,C_BG); tft.setTextColor(C_WHITE); tft.setCursor(175,35); tft.print("Score:"); tft.print(gameScore);
    }
  } else if (activeGame == GAME_SNAKE) {
    if (millis()-snakeTick >= 180) { snakeTick=millis(); gamePlayerX += snakeDX*8; gamePlayerY += snakeDY*8;
      if(gamePlayerX<10)gamePlayerX=300; if(gamePlayerX>300)gamePlayerX=10; if(gamePlayerY<45)gamePlayerY=195; if(gamePlayerY>195)gamePlayerY=45;
      tft.fillRect(9,44,302,158,C_BG); tft.drawRect(8,43,304,160,C_MUTED); tft.fillRect(gamePlayerX,gamePlayerY,8,8,C_TEAL); tft.fillCircle(gameObstacleX,gameObstacleY,4,C_RED);
    }
  }
  if (gameOver) { tft.fillRect(55, 90, 210, 55, C_RED); tft.setTextColor(C_WHITE); tft.setTextSize(2); tft.setCursor(105,108); tft.print("GAME OVER"); tft.setTextSize(1); }
}

void handleGameTap(int x, int y) {
  if (y >= 216) { screenNow = SCR_GAMES; gameStarted=false; drawCurrentScreen(); return; }
  if (gameOver) { startGame(activeGame); return; }
  if (activeGame == GAME_FLAPPY) { gameVelocity = -6; }
  else if (activeGame == GAME_DINO) { if (gamePlayerY >= 178) { gameVelocity=-10; gamePlayerY=150; } }
  else if (activeGame == GAME_LUDO) { gameScore += 1 + (esp_random()%6); tft.fillRect(130,91,60,55,C_WHITE); tft.setTextColor(C_BG); tft.setTextSize(3); tft.setCursor(151,105); tft.print(((gameScore-1)%6)+1); tft.setTextSize(1); }
  else if (activeGame == GAME_DOOM) { gameScore++; tft.fillRect(230,34,85,9,C_BG); tft.setTextColor(C_WHITE); tft.setCursor(230,35); tft.print(gameScore); }
  else if (activeGame == GAME_CHESS) { tft.drawRect(x-(x-60)%25, y-(y-43)%25, 25, 25, C_YELLOW); }
