  else if (activeGame == GAME_SPACE) { gamePlayerX = constrain(x, 12, 308); spaceShotY = gamePlayerY - 15; }
}

void networkTask(void *parameter) {
  (void)parameter;
  uint32_t lastStatusCheck = 0;
  for (;;) {
    if (millis() - lastStatusCheck >= 1000UL || lastStatusCheck == 0) {
      lastStatusCheck = millis();
      wifiReady = (WiFi.status() == WL_CONNECTED);
      if (wifiReady && !timeSyncRequested && time(nullptr) < 1700000000) {
        configTime(19800, 0, NTP1, NTP2); // India Standard Time (UTC+05:30)
        timeSyncRequested = true;
      }
      if (!wifiReady) timeSyncRequested = false;
    }

    if (wifiReady && !weatherFetchBusy &&
        (lastWeatherFetchMs == 0 || millis() - lastWeatherFetchMs >= 600000UL)) {
      fetchWeather();
    }
    vTaskDelay(pdMS_TO_TICKS(100));
  }
}

void fetchWeather() {
  if (WiFi.status() != WL_CONNECTED || weatherFetchBusy) return;
  weatherFetchBusy = true;
  lastWeatherFetchMs = millis();
  String newTemp = "-- C";
  String newWeather = "Weather unavailable";
  // Approximate Koppam/Pattambi, Kerala. Open-Meteo requires no API key.
  WiFiClientSecure client;
  client.setInsecure(); // Demo only; use certificate validation for security-sensitive deployments.
  HTTPClient http;
  const char *url = "https://api.open-meteo.com/v1/forecast?latitude=10.80&longitude=76.17&current=temperature_2m,relative_humidity_2m,weather_code&timezone=Asia%2FKolkata";
  if (http.begin(client, url)) {
    http.setTimeout(4500);
    int code = http.GET();
    if (code == HTTP_CODE_OK) {
      String body = http.getString();
      int p = body.indexOf("\"temperature_2m\":");
      if (p >= 0) {
        int st = p + 17, en = st;
        while (en < (int)body.length() && (isDigit(body[en]) || body[en] == '-' || body[en] == '.')) en++;
        if (en > st) newTemp = body.substring(st, en) + " C";
      }
      int c = body.indexOf("\"weather_code\":");
      String desc = "Weather";
      if (c >= 0) {
        int st = c + 15, en = st;
        while (en < (int)body.length() && isDigit(body[en])) en++;
        int wc = body.substring(st, en).toInt();
        if (wc == 0) desc = "Clear";
        else if (wc <= 3) desc = "Cloudy";
        else if (wc <= 48) desc = "Fog";
        else if (wc <= 67) desc = "Rain";
        else if (wc <= 77) desc = "Snow";
        else if (wc <= 82) desc = "Showers";
        else desc = "Thunderstorm";
      }
      newWeather = "Koppam " + newTemp + " " + desc;
    } else {
      newWeather = "Weather unavailable (HTTP " + String(code) + ")";
    }
    http.end();
  } else {
    newWeather = "Weather connection failed";
  }

  if (weatherMutex && xSemaphoreTake(weatherMutex, pdMS_TO_TICKS(100)) == pdTRUE) {
    weatherTemp = newTemp;
    weatherText = newWeather;
    xSemaphoreGive(weatherMutex);
  }
  weatherFetchBusy = false;
}

