void handleTouchCalibration(int rawX, int rawY) {
  if (calStep >= 4) return;
  calRawX[calStep] = rawX;
  calRawY[calStep] = rawY;
  calStep++;
  delay(250); // prevent one long press from being counted as multiple targets
  if (calStep >= 4) {
    // Average opposite corners to reduce small tap-position errors.
    // Preserve axis direction: the raw value at screen-left/top may be larger
    // than the value at screen-right/bottom on some touch rotations.
    touchRawXMin = (calRawX[0] + calRawX[3]) / 2; // screen left
    touchRawXMax = (calRawX[1] + calRawX[2]) / 2; // screen right
    touchRawYMin = (calRawY[0] + calRawY[1]) / 2; // screen top
    touchRawYMax = (calRawY[2] + calRawY[3]) / 2; // screen bottom
    // Reject invalid/near-zero ranges and keep safe defaults.
    if (abs(touchRawXMax - touchRawXMin) < 500 ||
        abs(touchRawYMax - touchRawYMin) < 500) {
      touchRawXMin = 200; touchRawXMax = 3900;
      touchRawYMin = 250; touchRawYMax = 3850;
      statusLine = "Calibration failed; defaults restored";
    } else {
      saveSettings();
      statusLine = "Touch calibration saved";
    }
    screenNow = SCR_SETTINGS;
    drawCurrentScreen();
  } else {
    drawTouchCalibration();
  }
}

void refreshFileList() {
