String urlEncode(const String &input) {
  const char *hex = "0123456789ABCDEF";
  String out;
  for (size_t i = 0; i < input.length(); i++) {
    uint8_t c = (uint8_t)input[i];
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~') out += (char)c;
    else if (c == ' ') out += "%20";
    else { out += '%'; out += hex[c >> 4]; out += hex[c & 15]; }
  }
  return out;
}

void sendTelegramMessage() {
  if (WiFi.status() != WL_CONNECTED) { statusLine = "Connect Wi-Fi first"; return; }
  if (!telegramBotToken.length() || !telegramChatId.length()) { statusLine = "Set Telegram token and chat ID"; return; }
  WiFiClientSecure client;
  client.setInsecure(); // Demo only: certificate validation is not configured.
  HTTPClient http;
  String url = "https://api.telegram.org/bot" + telegramBotToken + "/sendMessage";
  if (!http.begin(client, url)) { statusLine = "Telegram request failed"; return; }
  http.setTimeout(7000);
  http.addHeader("Content-Type", "application/x-www-form-urlencoded");
  String body = "chat_id=" + urlEncode(telegramChatId) + "&text=" + urlEncode(telegramMessage);
  int code = http.POST(body);
  statusLine = (code >= 200 && code < 300) ? "Telegram message sent" : "Telegram HTTP " + String(code);
  http.end();
}

void scanWifiNetworks() {
  WiFi.mode(WIFI_STA);
  statusLine = "Scanning nearby Wi-Fi...";
  tft.fillScreen(C_BG);
  drawHeader("SCANNING WI-FI");
  tft.setTextColor(C_WHITE); tft.setTextSize(1);
  tft.setCursor(15, 90); tft.print("Searching for networks...");
  int n = WiFi.scanNetworks(false, true);
  wifiScanCount = 0;
  for (int i = 0; i < n && wifiScanCount < 8; i++) {
    String name = WiFi.SSID(i);
    if (!name.length()) continue;
    bool duplicate = false;
    for (int j = 0; j < wifiScanCount; j++) if (wifiScanNames[j] == name) duplicate = true;
    if (!duplicate) {
      wifiScanNames[wifiScanCount] = name;
      wifiScanOpen[wifiScanCount] = (WiFi.encryptionType(i) == WIFI_AUTH_OPEN);
      wifiScanCount++;
    }
  }
  WiFi.scanDelete();
  screenNow = SCR_WIFI_SCAN;
  statusLine = wifiScanCount ? "Choose a Wi-Fi network" : "No networks found";
  drawCurrentScreen();
}

void openBrowserPage() {
  if (WiFi.status() != WL_CONNECTED) {
    browserPageText = "Connect to Wi-Fi first in Wi-Fi Settings.";
    browserScroll = 0;
    statusLine = "Browser needs Wi-Fi";
    drawCurrentScreen();
    return;
  }
  String url = browserUrl;
  if (!url.startsWith("http://") && !url.startsWith("https://")) url = "https://" + url;
  browserPageText = "Loading page...";
  browserScroll = 0;
  drawCurrentScreen();
  WiFiClient plainClient;
  WiFiClientSecure secureClient;
  HTTPClient http;
  bool isHttps = url.startsWith("https://");
  if (isHttps) secureClient.setInsecure(); // convenient demo; does not verify certificates
  bool began = isHttps ? http.begin(secureClient, url) : http.begin(plainClient, url);
  if (!began) {
    browserPageText = "Could not start request. Check URL.";
    statusLine = "Browser request failed";
    drawCurrentScreen();
    return;
  }
  http.setTimeout(9000);
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  int code = http.GET();
  if (code <= 0) {
    browserPageText = "Request failed: " + http.errorToString(code);
    statusLine = "Page load failed";
  } else {
    String body = http.getString();
    String out; out.reserve(1200);
    bool inTag = false;
    bool lastSpace = false;
    for (unsigned int i = 0; i < body.length() && out.length() < 1200; i++) {
      char c = body[i];
      if (c == '<') { inTag = true; if (!lastSpace) { out += ' '; lastSpace = true; } continue; }
      if (c == '>') { inTag = false; continue; }
      if (inTag) continue;
      if (c == '\n' || c == '\r' || c == '\t') c = ' ';
      if (c == '&') {
        if (body.substring(i, min((unsigned int)body.length(), i + 5)) == "&amp;") { c = '&'; i += 4; }
        else if (body.substring(i, min((unsigned int)body.length(), i + 4)) == "&lt;") { c = '<'; i += 3; }
        else if (body.substring(i, min((unsigned int)body.length(), i + 4)) == "&gt;") { c = '>'; i += 3; }
      }
      if (c == ' ') { if (!lastSpace) out += c; lastSpace = true; }
      else { out += c; lastSpace = false; }
    }
    out.trim();
    browserPageText = out.length() ? out : "Page loaded, but no readable text was found.";
    statusLine = "HTTP " + String(code) + " loaded";
  }
  http.end();
  browserScroll = 0;
  drawCurrentScreen();
}

void connectWifi() {
  if (!wifiSsid.length()) {
    statusLine = "Enter SSID first";
    return;
  }
  WiFi.mode(WIFI_STA);
  WiFi.begin(wifiSsid.c_str(), wifiPass.c_str());
  statusLine = "Connecting...";
  uint32_t start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 12000) {
    delay(100);
  }
  wifiReady = WiFi.status() == WL_CONNECTED;
  if (wifiReady) {
    configTime(19800, 0, NTP1, NTP2);
    statusLine = "Connected";
    // Weather refresh occurs in the main loop to keep the UI responsive.
  } else statusLine = "Connection failed";
}

void capturePhoto() {
  if (!cameraReady || !sdReady) {
    statusLine = "Camera or SD not ready";
    return;
  }
  camera_fb_t *fb = esp_camera_fb_get();
  if (!fb) {
    statusLine = "Camera capture failed";
    return;
  }
  char path[32];
  do {
    snprintf(path, sizeof(path), "/PHOTO_%04lu.jpg", (unsigned long)lastPhotoNumber++);
  } while (SD_MMC.exists(path));
  File f = SD_MMC.open(path, FILE_WRITE);
  if (f) {
    size_t n = f.write(fb->buf, fb->len);
    f.close();
    if (n == fb->len) {
      lastPhoto = String(path);
      statusLine = "Photo saved";
    } else statusLine = "SD write failed";
  }
  esp_camera_fb_return(fb);
}

void checkAlarm() {
  if (!alarmEnabled || alarmRinging || millis() - lastAlarmCheckMs < 1000) return;
  lastAlarmCheckMs = millis();
  struct tm ti;
  if (!getLocalTime(&ti, 5)) return;
  char now[6];
  strftime(now, sizeof(now), "%H:%M", &ti);
  static String lastTriggeredMinute = "";
  String current = String(now);
  if (current == alarmText && current != lastTriggeredMinute) {
    alarmRinging = true;
    lastTriggeredMinute = current;
    drawCurrentScreen();
  }
}

