    }
    if (key == "DEL" && pinEntry.length()) pinEntry.remove(pinEntry.length()-1);
    else if (key == "OK") {
      if (pinEntry == pinCode) { pinEntry = ""; screenNow = SCR_HOME; }
      else { pinEntry = ""; statusLine = "Wrong PIN"; }
    } else if (key.length() && pinEntry.length() < 8) pinEntry += key;
    drawCurrentScreen();
    return;
  }

  if (screenNow == SCR_KEYBOARD) {
    if (y >= 202) {
      if (x < 55) { if (keyboardText.length() < 120) keyboardText += " "; }
      else if (x < 108) { if (keyboardText.length()) keyboardText.remove(keyboardText.length()-1); }
      else if (x < 161) keyboardText = "";
      else if (x < 214) keyboardSymbols = !keyboardSymbols;
      else if (x < 267) keyboardShift = !keyboardShift;
      else {
        String val = keyboardText;
        screenNow = keyboardReturnScreen;
        bool connectAfterPassword = (keyboardTitle == "Wi-Fi password");
        if (keyboardTitle == "Wi-Fi network") wifiSsid = val;
        else if (keyboardTitle == "Wi-Fi password") wifiPass = val;
        else if (keyboardTitle == "Browser URL") browserUrl = val;
        else if (keyboardTitle == "Radio URL") radioUrl = val;
        else if (keyboardTitle == "Telegram bot token") telegramBotToken = val;
        else if (keyboardTitle == "Telegram chat ID") telegramChatId = val;
        else if (keyboardTitle == "Telegram message") telegramMessage = val;
        else if (keyboardTitle == "New PIN") { if (val.length() >= 4 && val.length() <= 8) pinCode = val; }
        else if (keyboardTitle == "Alarm time") { if (val.length() == 5 && val.charAt(2) == ':') alarmText = val; }
        saveSettings();
        if (connectAfterPassword) connectWifi();
        drawCurrentScreen();
        return;
      }
      drawCurrentScreen();
      return;
    }
    const char *alphaRows[] = {"1234567890", "qwertyuiop", "asdfghjkl", "zxcvbnm"};
    const char *symbolRows[] = {"1234567890", "!@#$%^&*()", "-_=+[]{};", ".,?/\\:;\"'"};
    int row = (y - 77) / 31;
    if (row >= 0 && row < 4) {
      const char *keys = keyboardSymbols ? symbolRows[row] : alphaRows[row];
      int len = strlen(keys);
      int bw = (row==3) ? 35 : (300 / len);
      int startX = (320 - bw*len)/2;
      int col = (x - startX) / bw;
      if (col >= 0 && col < len && keyboardText.length() < 120) {
        char ch = keys[col];
        if (!keyboardSymbols && keyboardShift && ch >= 'a' && ch <= 'z') ch = (char)(ch - 'a' + 'A');
        keyboardText += ch;
      }
    }
    drawCurrentScreen();
    return;
  }

  if (screenNow == SCR_WIFI_SCAN) {
    if (y >= 213) {
      if (x < 160) scanWifiNetworks();
      else { screenNow = SCR_WIFI; drawCurrentScreen(); }
      return;
    }
    if (y >= 53 && y < 208) {
      int index = (y - 53) / 31;
      if (index >= 0 && index < wifiScanCount && index < 5) {
        wifiSsid = wifiScanNames[index];
        wifiPass = "";
        if (wifiScanOpen[index]) {
          saveSettings();
          screenNow = SCR_WIFI;
          connectWifi();
          drawCurrentScreen();
        } else {
          startKeyboard("Wi-Fi password", wifiPass, SCR_WIFI);
        }
      }
      return;
    }
  }

  if (screenNow == SCR_HOME) {
    if (y >= 94 && y < 143) {
      if (x < 106) screenNow = SCR_CAMERA;
      else if (x < 212) screenNow = SCR_BROWSER;
      else screenNow = SCR_MUSIC;
    } else if (y >= 151 && y < 199) {
      if (x < 106) screenNow = SCR_WIFI;
      else if (x < 212) screenNow = SCR_ALARM;
      else screenNow = SCR_GAMES;
    } else if (y >= 207) {
      if (x < 106) screenNow = SCR_GALLERY;
      else if (x < 212) screenNow = SCR_SETTINGS;
      else screenNow = SCR_APPS;
    }
    drawCurrentScreen(); return;
  }

  if (screenNow == SCR_WIFI) {
    if (y >= 42 && y < 78) {
      startKeyboard("Wi-Fi network", wifiSsid, SCR_WIFI);
    } else if (y >= 82 && y < 116) {
      if (x < 160) scanWifiNetworks();
      else startKeyboard("Wi-Fi password", wifiPass, SCR_WIFI);
    } else if (y >= 124 && y < 158) {
      if (x < 160) { connectWifi(); drawCurrentScreen(); }
      else { WiFi.disconnect(true); wifiReady = false; drawCurrentScreen(); }
    } else if (y >= 166 && y < 200) {
      if (x >= 160) { screenNow = SCR_HOME; drawCurrentScreen(); }
      else {
        WiFi.mode(WIFI_AP_STA);
        bool ok = WiFi.softAP("TealPhone-Setup", "tealphone8");
        statusLine = ok ? ("Hotspot: " + WiFi.softAPIP().toString()) : "Hotspot start failed";
        drawCurrentScreen();
      }
    }
    return;
  }

  if (screenNow == SCR_ALARM) {
    if (y >= 105 && y < 139) {
      if (x < 160) startKeyboard("Alarm time", alarmText, SCR_ALARM);
      else { alarmEnabled = !alarmEnabled; saveSettings(); drawCurrentScreen(); }
    } else if (y >= 148 && y < 182) {
      if (x < 160) { alarmRinging = false; drawCurrentScreen(); }
      else { screenNow = SCR_HOME; drawCurrentScreen(); }
    }
    return;
  }

  if (screenNow == SCR_BROWSER) {
    if (y >= 96 && y < 126) {
      if (x < 105) startKeyboard("Browser URL", browserUrl, SCR_BROWSER);
      else if (x < 205) openBrowserPage();
      else { screenNow = SCR_HOME; drawCurrentScreen(); }
    } else if (y >= 220) {
      if (x < 105) browserScroll = max(0, browserScroll - 200);
      else if (x < 205) browserScroll = min(max(0, (int)browserPageText.length() - 1), browserScroll + 200);
      else { screenNow = SCR_HOME; }
      drawCurrentScreen();
    }
    return;
  }

  if (screenNow == SCR_MUSIC) {
    if (y >= 103 && y < 135) {
      if (x < 105) startKeyboard("Radio URL", radioUrl, SCR_MUSIC);
      else if (x < 205) { statusLine = "Audio hardware/decoder needed"; drawCurrentScreen(); }
      else { screenNow = SCR_HOME; drawCurrentScreen(); }
    }
    return;
  }

  if (screenNow == SCR_CAMERA) {
    if (y >= 91 && y < 129) {
      if (x < 160) { capturePhoto(); drawCurrentScreen(); }
      else { screenNow = SCR_GALLERY; drawCurrentScreen(); }
    } else if (y >= 139 && y < 177) {
      if (x >= 160) { screenNow = SCR_HOME; drawCurrentScreen(); }
      else { statusLine = "Video recorder not implemented"; drawCurrentScreen(); }
    }
    return;
  }

  if (screenNow == SCR_GALLERY) {
    if (y >= 110 && y < 145) {
      if (x < 160) { initSd(); drawCurrentScreen(); }
      else { screenNow = SCR_HOME; drawCurrentScreen(); }
    } else if (y >= 160 && y < 198) {
      if (x < 106) { screenNow = SCR_FORMAT_SD; drawCurrentScreen(); }
      else if (x < 212) { screenNow = SCR_HOME; drawCurrentScreen(); }
      else { initSd(); drawCurrentScreen(); }
    }
    return;
  }

  if (screenNow == SCR_FORMAT_SD) {
    if (y >= 150 && y < 192) {
      if (x < 160) {
        if (SD_MMC.cardType() != CARD_NONE && SD_MMC.format()) {
          sdReady = SD_MMC.begin("/sdcard", true);
          lastPhoto = "";
          statusLine = sdReady ? "SD formatted" : "Format done; remount failed";
        } else {
          statusLine = "SD format failed/no card";
        }
        screenNow = SCR_GALLERY;
      } else {
        screenNow = SCR_GALLERY;
      }
      drawCurrentScreen();
    }
    return;
  }

  if (screenNow == SCR_GAMEPLAY) { handleGameTap(x, y); return; }

  if (screenNow == SCR_GAMES) {
    if (y >= 43 && y < 79) { if (x < 160) startGame(GAME_FLAPPY); else startGame(GAME_DINO); }
    else if (y >= 85 && y < 121) { if (x < 160) startGame(GAME_CHESS); else startGame(GAME_LUDO); }
    else if (y >= 127 && y < 163) { if (x < 160) startGame(GAME_DOOM); else startGame(GAME_SPACE); }
    else if (y >= 181) { screenNow = SCR_HOME; drawCurrentScreen(); }
    return;
  }

  if (screenNow == SCR_SETTINGS) {
    if (y >= 48 && y < 82) {
      if (x < 160) startKeyboard("New PIN", "", SCR_SETTINGS);
      else enterSleep();
    } else if (y >= 90 && y < 124) {
      if (x < 160) startTouchCalibration();
      else { screenNow = SCR_HOME; drawCurrentScreen(); }
    } else if (y >= 132 && y < 166) {
      if (x < 160) { quickShadeOpen = true; drawQuickShade(); }
      else { screenNow = SCR_FORMAT_SD; drawCurrentScreen(); }
    } else if (y >= 174 && y < 207) {
      if (x < 160) { screenNow = SCR_PPG; ppgHaveSignal = false; ppgWaveIndex = 0; if (cameraReady) { esp_camera_deinit(); initCameraMode(true); } drawCurrentScreen(); }
      else { setTorch(!torchOn); drawCurrentScreen(); }
    } else if (y >= 208) { screenNow = SCR_SYSTEM_SETTINGS; drawCurrentScreen(); }
    return;
  }

  if (screenNow == SCR_SYSTEM_SETTINGS) {
    if (y >= 48 && y < 79) {
      if (x < 160) { darkTheme = !darkTheme; C_BG = darkTheme ? 0x0841 : 0xFFFF; C_PANEL = darkTheme ? 0x10A3 : 0xCE79; C_WHITE = darkTheme ? 0xFFFF : 0x0000; saveSettings(); drawCurrentScreen(); }
      else { screenNow = SCR_WIFI; drawCurrentScreen(); }
    } else if (y >= 83 && y < 114) {
      if (x < 160) { WiFi.mode(WIFI_AP_STA); bool ok = WiFi.softAP("TealPhone-Setup", "tealphone8"); statusLine = ok ? ("Hotspot: " + WiFi.softAPIP().toString()) : "Hotspot start failed"; }
      else { WiFi.softAPdisconnect(true); statusLine = "Hotspot stopped"; }
      drawCurrentScreen();
    } else if (y >= 118 && y < 149) {
      if (x < 160) backlightLevel = (backlightLevel > 32) ? backlightLevel - 32 : 0;
      else backlightLevel = (backlightLevel < 223) ? backlightLevel + 32 : 255;
      setBacklight(backlightLevel); saveSettings(); drawCurrentScreen();
    } else if (y >= 153 && y < 184) {
      if (x < 160) startKeyboard("New PIN", "", SCR_SYSTEM_SETTINGS);
      else startTouchCalibration();
    } else if (y >= 188 && y < 218) {
      if (x < 108) { screenNow = SCR_INTERNAL; drawCurrentScreen(); }
      else if (x < 212) { screenNow = SCR_ABOUT; drawCurrentScreen(); }
      else enterSleep();
    } else if (y >= 222) { screenNow = SCR_SETTINGS; drawCurrentScreen(); }
    return;
  }

  if (screenNow == SCR_ABOUT) {
    if (y >= 150) { screenNow = SCR_HOME; drawCurrentScreen(); }
    return;
  }

  if (screenNow == SCR_APPS) {
    if (y >= 42 && y < 76) {
      if (x < 160) { screenNow = SCR_FILES; filePage = 0; refreshFileList(); }
      else screenNow = SCR_INTERNAL;
    } else if (y >= 82 && y < 116) {
      if (x < 160) screenNow = SCR_MESSAGING;
      else { browserUrl = "https://m.youtube.com"; screenNow = SCR_BROWSER; }
    } else if (y >= 122 && y < 156) {
      if (x < 160) {
        WiFi.mode(WIFI_AP_STA);
        bool ok = WiFi.softAP("TealPhone-Setup", "tealphone8");
        statusLine = ok ? ("Hotspot TealPhone-Setup / " + WiFi.softAPIP().toString()) : "Hotspot failed";
      } else screenNow = SCR_CAMERA;
    } else if (y >= 162 && y < 196) {
      if (x < 160) screenNow = SCR_GAMES; else { screenNow = SCR_PPG; ppgHaveSignal = false; ppgWaveIndex = 0; if (cameraReady) { esp_camera_deinit(); initCameraMode(true); } }
    } else if (y >= 205) screenNow = SCR_HOME;
    drawCurrentScreen(); return;
  }

  if (screenNow == SCR_FILES) {
    if (y >= 52 && y < 202) {
      int idx = filePage * 5 + (y - 52) / 30;
      if (idx >= 0 && idx < fileCount) {
        String n = fileNames[idx];
        if (!n.startsWith("/")) n = "/" + n;
        if (n.endsWith(".jpg") || n.endsWith(".JPG")) {
          lastPhoto = n; screenNow = SCR_GALLERY;
        } else statusLine = "Selected: " + n.substring(0, 24);
      }
    } else if (y >= 207) {
      if (x < 105) { refreshFileList(); filePage = 0; }
      else if (x < 212) filePage = (filePage + 1) % max(1, (fileCount + 4) / 5);
      else screenNow = SCR_APPS;
    }
    drawCurrentScreen(); return;
  }

  if (screenNow == SCR_MESSAGING) {
    if (y >= 151 && y < 181) {
      if (x < 160) startKeyboard("Telegram bot token", telegramBotToken, SCR_MESSAGING);
      else startKeyboard("Telegram chat ID", telegramChatId, SCR_MESSAGING);
    } else if (y >= 188 && y < 218) {
      if (x < 160) startKeyboard("Telegram message", telegramMessage, SCR_MESSAGING);
      else { sendTelegramMessage(); drawCurrentScreen(); }
    } else if (y >= 221) { screenNow = SCR_APPS; drawCurrentScreen(); }
    return;
  }

  if (screenNow == SCR_BLUETOOTH) {
    if (y >= 140 && y < 174) {
      if (x < 160) bluetoothStatus = "BLE discovery not included in this build";
      else screenNow = SCR_APPS;
      drawCurrentScreen();
    }
    return;
  }

  if (screenNow == SCR_PPG) {
    if (y >= 200 || (y < 35 && x < 90)) {
      if (cameraReady) esp_camera_deinit();
      initCameraMode(false); ppgModeActive = false; screenNow = SCR_APPS; drawCurrentScreen();
    } else if (y >= 150 && x >= 160) { setTorch(!torchOn); drawPpgScreen(); }
    return;
  }

  if (screenNow == SCR_QUICK) {
    if (y >= 36 && y < 88) {
      if (x < 160) { setTorch(!torchOn); }
      else { WiFi.mode(WIFI_STA); if (WiFi.status() == WL_CONNECTED) WiFi.disconnect(); else if (wifiSsid.length()) WiFi.begin(wifiSsid.c_str(), wifiPass.c_str()); }
    } else if (y >= 88 && y < 140) {
      if (x < 160) { WiFi.mode(WIFI_AP_STA); WiFi.softAP("TealPhone-Setup", "tealphone8"); }
      else { bluetoothStatus = "BLE toggle requires BLE service integration"; }
    } else if (y >= 140 && y < 195) {
      if (x < 160) { if (x < 82) backlightLevel = (uint8_t)max(0, (int)backlightLevel - 32); else backlightLevel = (uint8_t)min(255, (int)backlightLevel + 32); setBacklight(backlightLevel); }
      else { screenNow = SCR_ABOUT; quickShadeOpen = false; drawCurrentScreen(); return; }
    } else if (y >= 195) {
      if (x < 160) { setTheme(!darkTheme); quickShadeOpen = false; screenNow = SCR_HOME; drawCurrentScreen(); return; }
      quickShadeOpen = false; screenNow = SCR_HOME; drawCurrentScreen(); return;
    }
    drawQuickShade(); return;
  }

  if (screenNow == SCR_INTERNAL) {
    if (y >= 207) {
      if (x < 160) { initInternalFs(); }
      else { screenNow = SCR_APPS; }
    }
    drawCurrentScreen(); return;
  }

  // Generic back behavior for unhandled areas.
  if (y < 30) { screenNow = SCR_HOME; drawCurrentScreen(); }
}
